using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class StructureControlOperations
{
    private static Button Button(Node parent,string text,string name=""){var button=new Button{Text=text};if(name.Length>0)button.Name=name;parent.AddChild(button);return button;}
    private static GArray Types=>GD.Load<GDScript>("res://scripts/actors/physics/structure/structure_definition.gd").GetScriptConstantMap()["TYPES"].AsGodotArray();
    public void build(VBoxContainer owner)
    {
        var host=Host(owner);if(!GodotObject.IsInstanceValid(host))return;var actor=Actor(owner);var model=Model(owner);var updaters=host.Get("_updaters").AsGodotArray();var callbacks=owner.Get("callbacks").AsGodotArray();foreach(var callback in callbacks)updaters.Remove(callback);callbacks.Clear();int start=updaters.Count;foreach(var child in owner.GetChildren()){owner.RemoveChild(child);child.QueueFree();}var links=Links(owner);string selected=owner.Get("selected").AsString();if(selected.Length==0)selected=actor.GetMeta("structure_selected","").AsString();if(!links.ContainsKey(selected))selected=links.Count>0?links.Keys.First().AsString():"";owner.Set("selected",selected);owner.Set("signature",Signature(owner,links));if(links.ContainsKey(selected)){string id=selected;var viewport=Button(owner,"◎  Edit joint in viewport","StructuralViewport");viewport.ToggleMode=true;viewport.ButtonPressed=actor.GetMeta("structure_tool",false).AsBool();viewport.Toggled+=value=>{actor.SetMeta("structure_tool",value);actor.SetMeta("structure_selected",id);};}var group=Button(owner,"＋  Assemble selection");group.TooltipText="Enable structural elements on selected meshes without changing their scene parenting or geometry.";group.Pressed+=()=>{var actors=new GArray();var changes=new GArray();string id=_data.new_id();foreach(var item in model.Call("selected_actors").AsGodotArray()){var data=item.As<Resource>();if(data.Get("type_id").AsString() is "basic_shape" or "basic_mesh"){actors.Add(data);changes.Add(new Settings{["structure_enabled"]=true,["structure_assembly"]=id});}}if(actors.Count>0)_structure.commit(model,actors,changes,"Create structural assembly");};
        var target=new OptionButton{Name="StructuralTarget",FitToLongestItem=false};owner.AddChild(target);var targets=new List<Resource>();foreach(var item in model.Get("actors").AsGodotArray()){var data=item.As<Resource>();if(data!=actor&&data.Get("type_id").AsString() is "basic_shape" or "basic_mesh"){target.AddItem(data.Get("display_name").AsString());targets.Add(data);}}var row=new HBoxContainer();owner.AddChild(row);var kinds=new OptionButton{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,FitToLongestItem=false};row.AddChild(kinds);foreach(var title in Types)kinds.AddItem(title.AsString());var create=Button(row,"＋","ConnectStructure");create.TooltipText="Connect this actor to the chosen target. Connections are explicit, not inferred from parenting.";create.Disabled=targets.Count==0;create.Pressed+=()=>{var other=targets[target.Selected];string id=_structure.connect_actors(model,actor,other,(pose(owner,actor).Origin+pose(owner,other).Origin)*.5f,pose(owner,actor),pose(owner,other),kinds.Selected);owner.Set("selected",id);actor.SetMeta("structure_selected",id);owner.CallDeferred("build");};
        var autoRow=new HBoxContainer();owner.AddChild(autoRow);var gap=new DragNumber();gap.Name="ConnectionTolerance";gap.MinValue=0;gap.MaxValue=10;gap.Step=.01;gap.Value=owner.Get("tolerance").AsDouble();gap.Suffix="m";gap.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;gap.TooltipText="Boundary tolerance for candidate review. Finding candidates never welds objects automatically.";autoRow.AddChild(gap);gap.ValueChanged+=value=>owner.Set("tolerance",value);gap.Connect("drag_committed",Callable.From<double>(value=>owner.Set("tolerance",value)));var find=Button(autoRow,"Find nearby");find.Pressed+=()=>{var bounds=new Settings();var actors=new GArray();var view=editor(owner);if(view==null)return;foreach(var item in model.Call("selected_actors").AsGodotArray()){var data=item.As<Resource>();if(data.Get("type_id").AsString() is not ("basic_shape" or "basic_mesh"))continue;var clip=model.Call("clip_for_actor_id",data.Get("id")).As<Resource>();if(clip==null)continue;var runtime=view.Call("_runtime_for_clip",clip.Get("id")).As<Node>();if(runtime==null)continue;actors.Add(data);bounds[data.Get("id")]=pose(owner,data)*_geometry.capture(runtime,new Settings())["bounds"].AsAabb();}var candidates=owner.Get("candidates").AsGodotArray();candidates.Clear();foreach(var candidate in _structure.candidates(actors,bounds,owner.Get("tolerance").AsDouble()))candidates.Add(candidate);owner.CallDeferred("build");};
        var candidatesList=owner.Get("candidates").AsGodotArray();foreach(var item in candidatesList){var candidate=item.AsGodotDictionary();var a=candidate["a"].As<Resource>();var b=candidate["b"].As<Resource>();var accept=Button(owner,"Link "+a.Get("display_name").AsString()+" ↔ "+b.Get("display_name").AsString());accept.ClipText=true;accept.TooltipText=$"Review bounds-based candidate (gap {candidate["gap"].AsDouble():F3} m). Click to explicitly add this joint.";accept.Pressed+=()=>{_structure.connect_actors(model,a,b,candidate["point"].AsVector3(),pose(owner,a),pose(owner,b),kinds.Selected);candidatesList.Remove(candidate);owner.CallDeferred("build");};}
        foreach(var entry in links){string key=entry.Key.AsString();var line=new HBoxContainer();owner.AddChild(line);var other=model.Call("actor_for_id",entry.Value.AsGodotDictionary().GetValueOrDefault("target","")).As<Resource>();var button=Button(line,other!=null?"⚭  "+other.Get("display_name").AsString():"⚠ Missing target");button.ToggleMode=true;button.ButtonPressed=key==selected;button.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;button.ClipText=true;button.Pressed+=()=>{owner.Set("selected",key);actor.SetMeta("structure_selected",key);owner.CallDeferred("build");};var remove=Button(line,"×");remove.TooltipText="Remove connection and its keyframes";remove.Pressed+=()=>{var updated=_data.copy_value(Links(owner)).AsGodotDictionary();updated.Remove(key);_structure.commit(model,new GArray{actor},new GArray{new Settings{["structure_connections"]=updated}},"Remove structural connection");owner.CallDeferred("build");};}
        foreach(var item in model.Get("actors").AsGodotArray()){var other=item.As<Resource>();foreach(var entry in _data.get_value(other,new StringName("structure_connections"),new Settings()).AsGodotDictionary()){string key=entry.Key.AsString();if(entry.Value.AsGodotDictionary().GetValueOrDefault("target","").AsString()!=actor.Get("id").AsString())continue;var incoming=Button(owner,"↖  From "+other.Get("display_name").AsString());incoming.ClipText=true;incoming.Pressed+=()=>{other.SetMeta("structure_selected",key);var clip=model.Call("clip_for_actor_id",other.Get("id")).As<Resource>();if(clip!=null)model.Call("select",clip.Get("id"),false);};}}
        if(links.ContainsKey(selected))BuildSelected(owner,selected,links[selected].AsGodotDictionary());var status=new Label{Name="StructuralStatus",AutowrapMode=TextServer.AutowrapMode.WordSmart};status.AddThemeFontSizeOverride("font_size",12);owner.AddChild(status);void Update(){if(!GodotObject.IsInstanceValid(status))return;var view=editor(owner);var state=view!=null?view.Get("physics").AsGodotObject().Get("display_states").AsGodotDictionary().GetValueOrDefault(actor.Get("id"),new Settings()).AsGodotDictionary().GetValueOrDefault("structural",new Settings()).AsGodotDictionary():new Settings();var joint=state.GetValueOrDefault("links",new Settings()).AsGodotDictionary().GetValueOrDefault(owner.Get("selected"),new Settings()).AsGodotDictionary();status.Text=(state.GetValueOrDefault("supported",false).AsBool()?"Supported":"Unanchored / contact-dependent")+$" · Approximate joint loads\n{joint.GetValueOrDefault("load",0).AsDouble():F1} N · {joint.GetValueOrDefault("torque",0).AsDouble():F1} N·m · {100*joint.GetValueOrDefault("utilization",0).AsDouble():F0}% used\n"+joint.GetValueOrDefault("reason","").AsString();}updaters.Add(Callable.From(Update));Update();host.Call("_prepare_buttons");for(int i=start;i<updaters.Count;i++)callbacks.Add(updaters[i]);
    }
    private void BuildSelected(VBoxContainer owner,string id,Settings link)
    {
        var kind=new OptionButton{FitToLongestItem=false};owner.AddChild(kind);foreach(var title in Types)kind.AddItem(title.AsString());int type=link["type"].AsInt32();kind.Select(type);kind.ItemSelected+=value=>{_structure.set_value(Model(owner),Actor(owner),id,"type",value,false);owner.CallDeferred("build");};foreach(string key in new[]{"enabled","prevent_failure","exclude_collision"})toggle(owner,id,key,link.GetValueOrDefault(key,true).AsBool(),null);foreach(string key in new[]{"strength","breaking_force","breaking_torque","stiffness","initial_damage","break_at"}){if(key=="breaking_torque"&&type is 3 or 4)continue;number(owner,id,key,link.GetValueOrDefault(key,0).AsDouble(),null,-1);}if(type is 3 or 4)number(owner,id,"length",link["length"].AsDouble(),null,-1);if(type==2)number(owner,id,"limit",link["limit"].AsDouble(),null,-1);if(type==3)toggle(owner,id,"tension_only",link["tension_only"].AsBool(),null);var advanced=Button(owner,"Joint details  ▾");advanced.ToggleMode=true;var details=new VBoxContainer();details.Hide();owner.AddChild(details);advanced.Toggled+=details.SetVisible;foreach(string key in new[]{"angular_stiffness","tension","compression","shear","bending","damping","damage_rate"}){if(key is "angular_stiffness" or "bending"&&type is 3 or 4)continue;number(owner,id,key,link.GetValueOrDefault(key,1).AsDouble(),details,-1);}toggle(owner,id,"material_strength",link.GetValueOrDefault("material_strength",false).AsBool(),details);foreach(string key in new[]{"pivot","target_pivot","orientation"})for(int axis=0;axis<3;axis++)number(owner,id,key,link.GetValueOrDefault(key,Vector3.Zero).AsVector3()[axis],details,axis);
    }
}
